/**
 * `effect-surrealkit`: reads a SurrealKit schema document v2 (stdin or
 * `--input`) and writes Effect modules to `--out`.
 *
 * Writes are atomic per file (temp file + rename), unchanged files are left
 * untouched, and generated files that are no longer produced are removed.
 * `--check` writes nothing and exits 1 when the directory differs from what
 * would be generated (missing, changed, hand-edited or stale files).
 */
import { createHash, randomBytes } from 'node:crypto';
import {
	mkdir,
	readdir,
	readFile,
	rename,
	rm,
	writeFile,
} from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { parseArgs } from 'node:util';

import { Effect } from 'effect';

import { type GeneratedFile, generate } from '../emitter/generate.js';
import { EMITTER_VERSION } from '../emitter/version.js';

export const USAGE = `Usage: effect-surrealkit --out <dir> [options] [< schema.json]

Generates Effect v4 modules from a SurrealKit schema document v2.

Options:
  --input <file>             Read the schema document from a file (default: stdin)
  --out <dir>                Output directory (required)
  --config <file>            Emitter options as JSON: store, int, datetime, patch,
                             importExtension, acknowledge, fields, names
  --store <name>             Logical store name, used in record-id brands
  --int <profile>            safe-number (default) | bigint
  --datetime <profile>       sdk (default) | effect-datetime
  --patch                    Also emit JSON Patch unions (not yet qualified)
  --import-extension <ext>   .js (default) | .ts: extension of imports between the
                             generated modules; .ts loads under Node type stripping
  --acknowledge <code=why>   Proceed past an error diagnostic code (repeatable)
  --check                    Write nothing; exit 1 if the output is not up to date
  --help                     Show this help
  --version                  Show the emitter version

As a SurrealKit external emitter ([typegen.emit.<name>], which sets
SURREALKIT_EMIT_PROTOCOL=1), it reads the document on stdin and prints the
protocol 1 reply on stdout instead of writing files; SurrealKit writes them,
so --out, --input and --check are refused there. The project's
[typegen] acknowledge (SURREALKIT_EMIT_ACKNOWLEDGE) counts as --acknowledge:

  [typegen.emit.effect]
  command = "effect-surrealkit --store app"
  out = "src/generated/surreal"

Exit codes: 0 success, 1 generation failed or output out of date, 2 bad arguments.
`;

/** First line of every generated file; marks the files this tool owns. */
const GENERATED_MARK = '// Generated by effect-surrealkit';

/** The external-emitter protocol version this emitter speaks. */
const EMIT_PROTOCOL = '1';

export interface CliIo {
	readonly cwd: string;
	readonly stdin: () => Promise<string>;
	readonly stdout: (text: string) => void;
	readonly stderr: (text: string) => void;
	/** The process environment; `SURREALKIT_EMIT_PROTOCOL` selects protocol mode. */
	readonly env?: Readonly<Record<string, string | undefined>>;
}

class UsageError extends Error {}

const parseJson = (text: string, what: string): unknown => {
	try {
		return JSON.parse(text);
	} catch (error) {
		throw new UsageError(
			`${what} is not valid JSON: ${(error as Error).message}`,
		);
	}
};

interface Drift {
	readonly missing: ReadonlyArray<string>;
	readonly changed: ReadonlyArray<string>;
	readonly stale: ReadonlyArray<string>;
}

const generatedFilesIn = async (dir: string): Promise<Map<string, string>> => {
	const found = new Map<string, string>();
	let entries: string[];
	try {
		entries = await readdir(dir);
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === 'ENOENT') return found;
		throw error;
	}
	for (const entry of entries.sort()) {
		if (!entry.endsWith('.ts')) continue;
		const content = await readFile(join(dir, entry), 'utf8');
		if (content.startsWith(GENERATED_MARK)) found.set(entry, content);
	}
	return found;
};

const compareWith = async (
	dir: string,
	files: ReadonlyArray<GeneratedFile>,
): Promise<Drift> => {
	const existing = await generatedFilesIn(dir);
	const missing: string[] = [];
	const changed: string[] = [];
	for (const file of files) {
		// A file at a generated path without the mark was hand-written or edited.
		const current =
			existing.get(file.path) ??
			(await readFile(join(dir, file.path), 'utf8').catch(
				() => undefined,
			));
		if (current === undefined) missing.push(file.path);
		else if (current !== file.content) changed.push(file.path);
	}
	const produced = new Set(files.map((file) => file.path));
	const stale = [...existing.keys()].filter((path) => !produced.has(path));
	return { missing, changed, stale };
};

const writeAtomic = async (path: string, content: string): Promise<void> => {
	const temp = `${path}.${randomBytes(6).toString('hex')}.tmp`;
	await writeFile(temp, content, 'utf8');
	try {
		await rename(temp, path);
	} catch (error) {
		await rm(temp, { force: true });
		throw error;
	}
};

const readOptions = async (
	values: {
		readonly config?: string | undefined;
		readonly store?: string | undefined;
		readonly int?: string | undefined;
		readonly datetime?: string | undefined;
		readonly patch?: boolean | undefined;
		readonly 'import-extension'?: string | undefined;
		readonly acknowledge?: ReadonlyArray<string> | undefined;
	},
	cwd: string,
	inherited: Readonly<Record<string, string>>,
): Promise<Record<string, unknown>> => {
	const config =
		values.config === undefined
			? {}
			: parseJson(
					await readFile(resolve(cwd, values.config), 'utf8'),
					`--config ${values.config}`,
				);
	if (
		typeof config !== 'object' ||
		config === null ||
		Array.isArray(config)
	) {
		throw new UsageError('--config must hold a JSON object');
	}
	const base = config as Record<string, unknown>;
	const acknowledge: Record<string, unknown> = {
		...inherited,
		...((base.acknowledge as Record<string, unknown> | undefined) ?? {}),
	};
	for (const entry of values.acknowledge ?? []) {
		const separator = entry.indexOf('=');
		if (separator <= 0 || separator === entry.length - 1) {
			throw new UsageError(
				`--acknowledge expects <code>=<reason>, got ${JSON.stringify(entry)}`,
			);
		}
		acknowledge[entry.slice(0, separator)] = entry.slice(separator + 1);
	}
	return {
		...base,
		...(values.store !== undefined && { store: values.store }),
		...(values.int !== undefined && { int: values.int }),
		...(values.datetime !== undefined && { datetime: values.datetime }),
		...(values.patch !== undefined && { patch: values.patch }),
		...(values['import-extension'] !== undefined && {
			importExtension: values['import-extension'],
		}),
		...(Object.keys(acknowledge).length > 0 && { acknowledge }),
	};
};

/**
 * `[typegen] acknowledge` as SurrealKit passes it to emitters: a JSON object of
 * diagnostic code to a non-empty reason.
 */
const projectAcknowledgements = (
	raw: string | undefined,
): Record<string, string> => {
	if (raw === undefined || raw === '') return {};
	const parsed = parseJson(raw, 'SURREALKIT_EMIT_ACKNOWLEDGE');
	const invalid = () =>
		new UsageError(
			'SURREALKIT_EMIT_ACKNOWLEDGE must be a JSON object of diagnostic code to reason',
		);
	if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed))
		throw invalid();
	const acknowledged: Record<string, string> = {};
	for (const [code, reason] of Object.entries(parsed)) {
		if (code === '' || typeof reason !== 'string' || reason.trim() === '')
			throw invalid();
		acknowledged[code] = reason;
	}
	return acknowledged;
};

const execute = async (
	argv: ReadonlyArray<string>,
	io: CliIo,
): Promise<number> => {
	const { values } = parseArgs({
		args: [...argv],
		options: {
			input: { type: 'string' },
			out: { type: 'string' },
			config: { type: 'string' },
			store: { type: 'string' },
			int: { type: 'string' },
			datetime: { type: 'string' },
			patch: { type: 'boolean' },
			'import-extension': { type: 'string' },
			acknowledge: { type: 'string', multiple: true },
			check: { type: 'boolean' },
			help: { type: 'boolean' },
			version: { type: 'boolean' },
		},
		strict: true,
		allowPositionals: false,
	});
	if (values.help) {
		io.stdout(USAGE);
		return 0;
	}
	if (values.version) {
		io.stdout(`${EMITTER_VERSION}\n`);
		return 0;
	}
	const protocol = io.env?.SURREALKIT_EMIT_PROTOCOL;
	if (protocol !== undefined) {
		if (protocol !== EMIT_PROTOCOL) {
			io.stderr(
				`effect-surrealkit: SurrealKit asked for external-emitter protocol ${JSON.stringify(protocol)}; this emitter speaks protocol ${EMIT_PROTOCOL}\n`,
			);
			return 1;
		}
		for (const flag of ['out', 'input', 'check'] as const) {
			if (values[flag] !== undefined)
				throw new UsageError(
					`--${flag} is not allowed when SurrealKit runs the emitter (SURREALKIT_EMIT_PROTOCOL is set): SurrealKit reads the document, writes the files and checks them`,
				);
		}
	} else if (values.out === undefined)
		throw new UsageError('--out <dir> is required');

	const options = await readOptions(
		values,
		io.cwd,
		protocol === undefined
			? {}
			: projectAcknowledgements(io.env?.SURREALKIT_EMIT_ACKNOWLEDGE),
	);
	const source =
		values.input === undefined
			? await io.stdin()
			: await readFile(resolve(io.cwd, values.input), 'utf8');
	const document = parseJson(source, values.input ?? 'stdin');
	const result = await Effect.runPromise(
		Effect.result(
			generate(document, options, {
				sha256: (text) =>
					createHash('sha256').update(text, 'utf8').digest('hex'),
			}),
		),
	);
	if (result._tag === 'Failure') {
		io.stderr(`effect-surrealkit: ${result.failure.message}\n`);
		return 1;
	}
	const { files, warnings } = result.success;
	for (const warning of warnings) {
		// SurrealKit reports the document's own diagnostics itself.
		if (protocol !== undefined && warning.startsWith('document: '))
			continue;
		io.stderr(`effect-surrealkit: warning: ${warning}\n`);
	}

	if (protocol !== undefined || values.out === undefined) {
		const reply = {
			protocol: Number(EMIT_PROTOCOL),
			files: files.map((file) => ({
				path: file.path,
				contents: file.content,
			})),
		};
		io.stdout(`${JSON.stringify(reply)}\n`);
		return 0;
	}

	const out = resolve(io.cwd, values.out);
	const drift = await compareWith(out, files);
	if (values.check) {
		const problems = [
			...drift.missing.map((path) => `missing: ${path}`),
			...drift.changed.map((path) => `out of date or edited: ${path}`),
			...drift.stale.map((path) => `stale: ${path}`),
		];
		if (problems.length > 0) {
			io.stderr(
				`effect-surrealkit: ${out} is not up to date:\n${problems.map((p) => `  ${p}`).join('\n')}\n`,
			);
			return 1;
		}
		return 0;
	}
	await mkdir(out, { recursive: true });
	for (const file of files) {
		if (
			drift.missing.includes(file.path) ||
			drift.changed.includes(file.path)
		) {
			await writeAtomic(join(out, file.path), file.content);
		}
	}
	for (const path of drift.stale) await rm(join(out, path));
	const touched =
		drift.missing.length + drift.changed.length + drift.stale.length;
	io.stderr(
		`effect-surrealkit: ${files.length} modules in ${out} (${touched === 0 ? 'unchanged' : `${touched} updated`})\n`,
	);
	return 0;
};

/** Runs the CLI; resolves to the exit code. */
export const run = async (
	argv: ReadonlyArray<string>,
	io: CliIo,
): Promise<number> => {
	try {
		return await execute(argv, io);
	} catch (error) {
		const usage =
			error instanceof UsageError ||
			String((error as { code?: unknown }).code ?? '').startsWith(
				'ERR_PARSE_ARGS',
			);
		io.stderr(
			`effect-surrealkit: ${(error as Error).message}\n${usage ? `\n${USAGE}` : ''}`,
		);
		return usage ? 2 : 1;
	}
};
